-- Pharmacy DB: schema fixes. Run once, inside a transaction.
-- Take a backup first:  pg_dump -U postgres pharmacy > backup.sql
BEGIN;

-- 1. Auto-generated IDs (identity columns), continuing after existing max values
ALTER TABLE customers      ALTER COLUMN cust_no  ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE employee       ALTER COLUMN emp_no   ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE medicine       ALTER COLUMN med_no   ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE medicine_batch ALTER COLUMN batch_no ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE prescription   ALTER COLUMN pres_no  ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE purchase_order ALTER COLUMN pur_no   ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE sale           ALTER COLUMN bill_no  ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE supplier       ALTER COLUMN sup_no   ADD GENERATED BY DEFAULT AS IDENTITY;

SELECT setval(pg_get_serial_sequence('customers','cust_no'),      COALESCE(MAX(cust_no),0)+1,  false) FROM customers;
SELECT setval(pg_get_serial_sequence('employee','emp_no'),        COALESCE(MAX(emp_no),0)+1,   false) FROM employee;
SELECT setval(pg_get_serial_sequence('medicine','med_no'),        COALESCE(MAX(med_no),0)+1,   false) FROM medicine;
SELECT setval(pg_get_serial_sequence('medicine_batch','batch_no'),COALESCE(MAX(batch_no),0)+1, false) FROM medicine_batch;
SELECT setval(pg_get_serial_sequence('prescription','pres_no'),   COALESCE(MAX(pres_no),0)+1,  false) FROM prescription;
SELECT setval(pg_get_serial_sequence('purchase_order','pur_no'),  COALESCE(MAX(pur_no),0)+1,   false) FROM purchase_order;
SELECT setval(pg_get_serial_sequence('sale','bill_no'),           COALESCE(MAX(bill_no),0)+1,  false) FROM sale;
SELECT setval(pg_get_serial_sequence('supplier','sup_no'),        COALESCE(MAX(sup_no),0)+1,   false) FROM supplier;

-- 2. char(50) -> varchar (removes space padding)
ALTER TABLE medicine       ALTER COLUMN category TYPE varchar(50) USING rtrim(category);
ALTER TABLE purchase_order ALTER COLUMN status   TYPE varchar(50) USING rtrim(status);

-- 3. Quantity sold should be a whole number, like stock
ALTER TABLE sale_details ALTER COLUMN qty_sold TYPE integer USING round(qty_sold)::integer;

-- 4. NOT NULL on columns that must always be present
ALTER TABLE medicine_batch ALTER COLUMN med_no   SET NOT NULL;
ALTER TABLE sale_details   ALTER COLUMN med_no   SET NOT NULL;
ALTER TABLE medicine       ALTER COLUMN med_name SET NOT NULL;
ALTER TABLE supplier       ALTER COLUMN sup_name SET NOT NULL;
ALTER TABLE employee       ALTER COLUMN emp_name SET NOT NULL;

-- 5. Data validation (CHECK constraints)
ALTER TABLE customers DROP CONSTRAINT IF EXISTS chk_cust_age;
ALTER TABLE customers      ADD CONSTRAINT chk_cust_age     CHECK (age IS NULL OR age BETWEEN 0 AND 120);
ALTER TABLE employee DROP CONSTRAINT IF EXISTS chk_emp_salary;
ALTER TABLE employee       ADD CONSTRAINT chk_emp_salary   CHECK (salary IS NULL OR salary >= 0);
ALTER TABLE medicine DROP CONSTRAINT IF EXISTS chk_med_mrp;
ALTER TABLE medicine       ADD CONSTRAINT chk_med_mrp      CHECK (mrp IS NULL OR mrp >= 0);
ALTER TABLE medicine_batch DROP CONSTRAINT IF EXISTS chk_batch_stock;
ALTER TABLE medicine_batch ADD CONSTRAINT chk_batch_stock  CHECK (qty_in_stock >= 0);
ALTER TABLE medicine_batch DROP CONSTRAINT IF EXISTS chk_batch_price;
ALTER TABLE medicine_batch ADD CONSTRAINT chk_batch_price  CHECK (pur_price IS NULL OR pur_price >= 0);
ALTER TABLE medicine_batch DROP CONSTRAINT IF EXISTS chk_batch_dates;
ALTER TABLE medicine_batch ADD CONSTRAINT chk_batch_dates  CHECK (exp_date IS NULL OR mfg_date IS NULL OR exp_date > mfg_date);
ALTER TABLE sale_details DROP CONSTRAINT IF EXISTS chk_saled_qty;
ALTER TABLE sale_details   ADD CONSTRAINT chk_saled_qty    CHECK (qty_sold > 0);
ALTER TABLE sale_details DROP CONSTRAINT IF EXISTS chk_saled_price;
ALTER TABLE sale_details   ADD CONSTRAINT chk_saled_price  CHECK (sale_price >= 0);
ALTER TABLE purchase_order_details DROP CONSTRAINT IF EXISTS chk_pod_qty;
ALTER TABLE purchase_order_details ADD CONSTRAINT chk_pod_qty CHECK (qty_ordered > 0);
ALTER TABLE purchase_order DROP CONSTRAINT IF EXISTS chk_po_status;
ALTER TABLE purchase_order ADD CONSTRAINT chk_po_status
    CHECK (status IN ('Pending','Delivered','Cancelled'));
ALTER TABLE sale DROP CONSTRAINT IF EXISTS chk_sale_payment;
ALTER TABLE sale           ADD CONSTRAINT chk_sale_payment
    CHECK (payment_mode IN ('Cash','Card','UPI'));

-- 6. Indexes for foreign keys and common searches
CREATE INDEX IF NOT EXISTS idx_batch_med        ON medicine_batch(med_no);
CREATE INDEX IF NOT EXISTS idx_batch_exp        ON medicine_batch(exp_date);
CREATE INDEX IF NOT EXISTS idx_sale_cust        ON sale(cust_no);
CREATE INDEX IF NOT EXISTS idx_sale_emp         ON sale(emp_no);
CREATE INDEX IF NOT EXISTS idx_sale_date        ON sale(sale_date);
CREATE INDEX IF NOT EXISTS idx_saled_batch      ON sale_details(batch_no);
CREATE INDEX IF NOT EXISTS idx_saled_med        ON sale_details(med_no);
CREATE INDEX IF NOT EXISTS idx_pres_cust        ON prescription(cust_no);
CREATE INDEX IF NOT EXISTS idx_po_sup           ON purchase_order(sup_no);
CREATE INDEX IF NOT EXISTS idx_med_name         ON medicine(lower(med_name));

COMMIT;
